package com.yeyamo_mobile.api.moderation_trust_service.infrastructure.persistence;import java.time.Instant;import jakarta.persistence.*;
@Entity@Table(name="trust_scores")public class TrustScoreEntity{@Id@Column(name="subject_id",length=120)private String subjectId;@Column(nullable=false)private int score;@Column(name="approved_reports",nullable=false)private int approvedReports;@Column(name="rejected_reports",nullable=false)private int rejectedReports;@Column(name="updated_at",nullable=false)private Instant updatedAt;@Version private long version;public String getSubjectId(){return subjectId;}public void setSubjectId(String v){subjectId=v;}public int getScore(){return score;}public void setScore(int v){score=v;}public int getApprovedReports(){return approvedReports;}public void setApprovedReports(int v){approvedReports=v;}public int getRejectedReports(){return rejectedReports;}public void setRejectedReports(int v){rejectedReports=v;}public Instant getUpdatedAt(){return updatedAt;}public void setUpdatedAt(Instant v){updatedAt=v;}public long getVersion(){return version;}public void setVersion(long v){version=v;}}
